  "items": [
    {
      "title": "IAB Establishment Panel (IAB-Betriebspanel), 1993–2024",
      "url_or_doi": "https://fdz.iab.de/en/our-data-products/establishment-data/iab-establishment-panel/",
      "justification": "One of Germany's most comprehensive longitudinal datasets on business management, organisational structures and employment practices. Conducted annually by the Institute for Employment Research (IAB), it includes observations from 2020–2024. Variables cover personnel management, recruitment, workforce development, employee training, investment, innovation, working arrangements and business performance. Particularly relevant for studying organisational change, human resource management and industrial management in Germany during the 2020s. Research access is restricted."
    },
    {
      "title": "Mannheim Innovation Panel (MIP) – Innovation Activities of German Enterprises",
      "url_or_doi": "https://www.zew.de/en/research-data/mannheim-innovation-panel",
      "justification": "An annual representative enterprise survey conducted by the ZEW Leibniz Centre for European Economic Research. It provides firm-level information on innovation management, organisational innovation, technological development, research and development expenditure, digital transformation and business strategies. The panel includes observations from the 2020s and covers manufacturing and service industries. Particularly valuable for analysing how German businesses organise and manage innovation. Microdata access is available to researchers under specific conditions."
    },
    {
      "title": "Mannheim Enterprise Panel (MUP) – German Firm-Level Business Dynamics",
      "url_or_doi": "https://www.zew.de/en/research-data/mannheim-enterprise-panel",
      "justification": "A comprehensive longitudinal database covering more than nine million German companies. It contains information on company formation, closure, employment, turnover, industry classification, legal structure, ownership and financial characteristics. Its coverage extends into the 2020s, making it suitable for studying organisational development, corporate restructuring, entrepreneurship, industrial dynamics and business growth. Firm-level datasets and indicators are available through ZEW, with access conditions and potential fees."
    },
    {
      "title": "German Federal Statistical Office – Enterprise Births and Deaths by Industry and Employment Size",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/52111/table/52111-0011",
      "justification": "An official German enterprise demography dataset covering 2018–2024. It provides annual information on enterprise creation and closure, business survival dynamics, employment and enterprise size across economic sectors. Particularly relevant for examining organisational restructuring, industrial entrepreneurship, market entry and exit, and structural changes in German business activity during the 2020s. The statistical tables are publicly accessible and downloadable."
    },
    {
      "title": "Destatis GENESIS-Online – Structural Business Statistics by Enterprise Size and Economic Activity",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/48121/table/48121-0002",
      "justification": "An official statistical dataset covering 2008–2024, including the 2020s. It provides detailed information on enterprises, employment, turnover, investment, gross value added, personnel expenditure, wages and operating performance. Data can be disaggregated by enterprise size and economic sector. Especially useful for researching industrial organisation, business productivity, resource allocation, enterprise performance and structural differences between German industries. Data are publicly available."
    },
    {
      "title": "KfW SME Panel – German Small and Medium-Sized Enterprise Management",
      "url_or_doi": "https://www.kfw.de/About-KfW/KfW-Research/KfW-Mittelstandspanel.html",
      "justification": "An annual representative survey of German small and medium-sized enterprises, with editions covering 2020–2025. It examines business performance, investment decisions, financing structures, innovation, digitalisation and enterprise development. The dataset is particularly useful for analysing strategic management, financial management, organisational adaptation and business resilience among German SMEs during the 2020s. Public reports provide aggregated statistical findings, while underlying microdata are not openly downloadable."
    },
    {
      "title": "IAB Panel – Establishments in the COVID-19 Crisis (2020–2022)",
      "url_or_doi": "https://doi.org/10.5164/IAB.FDZD.2209.en.v1",
      "justification": "A longitudinal survey of German establishments conducted between August 2020 and June 2022. It includes 24 survey waves, with approximately 1,500–2,000 establishments surveyed per wave. The data capture organisational responses to the COVID-19 pandemic, employment adjustments and changing business conditions. Particularly relevant for studying crisis management, organisational resilience and workforce management during the early 2020s. The DOI identifies the dataset documentation; access to underlying research data is controlled."
    },
    {
      "title": "IAB Establishment History Panel (Betriebs-Historik-Panel, BHP)",
      "url_or_doi": "https://fdz.iab.de/en/our-data-products/establishment-data/bhp/",
      "justification": "A longitudinal administrative dataset covering establishments in Germany, maintained by the Institute for Employment Research. It includes establishment-level employment characteristics and information about workforce composition, economic activity and regional location. Its longitudinal structure supports analyses of establishment growth, contraction, workforce organisation and industrial restructuring during the 2020s. Particularly suitable for quantitative research on organisational dynamics and labour allocation. Access requires approval through the IAB Research Data Centre."
    },
    {
      "title": "Linked Employer-Employee Data of the IAB (LIAB)",
      "url_or_doi": "https://fdz.iab.de/en/our-data-products/overview-of-available-data/central-fdz-data-products/",
      "justification": "A linked employer-employee research dataset combining German establishment surveys with administrative employee records. Available versions include observations from the 2020s. It enables analyses of relationships between organisational management, employee characteristics, remuneration, workforce composition and business outcomes. Particularly valuable for investigating human resource management, organisational inequality, employment structures and the effects of management decisions on employees. Access is restricted to approved researchers."
    },
    {
      "title": "Eurostat – ICT Usage and E-Commerce in Enterprises: Germany",
      "url_or_doi": "https://ec.europa.eu/eurostat/web/digital-economy-and-society/information-data",
      "justification": "An annually updated European statistical dataset containing country-specific information for Germany throughout the 2020s. It measures enterprise adoption of digital technologies, cloud computing, electronic commerce, artificial intelligence and other information and communication technologies. Data can be analysed by industry and enterprise size. Particularly useful for studying digital management, technology adoption, organisational modernisation and digital transformation in German businesses. Aggregated statistics are publicly accessible."
    },
    {
      "title": "IAB Job Vacancy Survey (IAB-Stellenerhebung)",
      "url_or_doi": "https://fdz.iab.de/en/our-data-products/establishment-data/",
      "justification": "A recurring representative employer survey conducted by the Institute for Employment Research. It provides information on recruitment activities, vacancies, hiring difficulties, labour demand and personnel requirements in German establishments. Survey observations from the 2020s make it relevant for studying human resource management, workforce planning, skills shortages and recruitment strategies across German industries. Detailed research data are available through controlled access arrangements."
    },
    {
      "title": "IAB/ZEW Start-up Panel – German Young Enterprises",
      "url_or_doi": "https://fdz.iab.de/en/our-data-products/establishment-data/",
      "justification": "A firm-level research dataset focused on young businesses in Germany. It supports analyses of business development, employment growth, entrepreneurial activity and the evolution of newly established firms. Particularly relevant for studying organisational formation, start-up management, growth strategies and employment structures among German enterprises. Researchers should verify the observation years available in the specific dataset release before selecting it for a study restricted to the 2020s."
    },
    {
      "title": "ZEW Research Data Centre – German Firm-Level Innovation and Industrial Dynamics Data",
      "url_or_doi": "https://www.zew.de/en/zew-research-data-centre/provided-data",
      "justification": "A research data catalogue offering access to multiple German enterprise-level datasets, including innovation surveys, start-up panels and other business research data. Its collections support studies of corporate strategy, innovation management, organisational development, entrepreneurship and industrial dynamics. Several underlying datasets contain observations from the 2020s. This is particularly useful for identifying specialised business management datasets and obtaining research microdata that are not publicly downloadable."
    },
    {
      "title": "KfW SME Panel 2025 – Business Performance, Investment and Financial Management",
      "url_or_doi": "https://www.kfw.de/About-KfW/Service/Download-Center/Research-%28EN%29/KfW-Mittelstandspanel/",
      "justification": "The 2025 edition of the KfW SME Panel provides a statistical overview of German small and medium-sized enterprises, including business developments during 2024. Its findings cover turnover, employment, profitability, financing, investment and business resilience. Particularly valuable for examining financial management, strategic investment decisions and organisational responses to economic pressures in Germany during the mid-2020s. Published statistical reports are openly accessible, although firm-level microdata are not provided as an open download."
    }
  ]
}
